import{z as C,x as D,o as t,c as d,q as l,j as i,D as e,d as r,s as o,S as n,b as E}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"掩模 CD 均匀性","description":"","frontmatter":{"title":"掩模 CD 均匀性","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/mask-cdu.md","filePath":"litho/mask-cdu.md","lastUpdated":1791063341000}'),A={name:"litho/mask-cdu.md"};function p(B,a,m,h,u,F){const s=D("Mermaid");return t(),d("div",null,[a[2]||(a[2]=l('<h1 id="掩模-cd-均匀性" tabindex="-1">掩模 CD 均匀性 <a class="header-anchor" href="#掩模-cd-均匀性" aria-label="Permalink to &quot;掩模 CD 均匀性&quot;">​</a></h1><div class="epigraph"><p>Mask CDU 是版上同一目标宽度的空间离散；晶圆看到的是它乘 MEF，不是掩模 SEM 那张图自己。</p><footer>—— 对照 ITRS/IRDS 掩模误差预算与 MEF 放大的通称</footer></div><p><a href="/litho/write-grid-shot-count">上一课</a>把边钉在写栅上。缺口是全场、全版的 CD 并不因此变平：PEC 残差、刻蚀负载、胶厚、雾化底板都会留下指纹。本课钉 mask CDU。图形放在哪（配准），留给<a href="/litho/mask-registration">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/litho/mask-cd-ppe">掩模 CD 与放置</a> 已把误差写成进晶圆的语言。本课补制造侧：CDU 要拆全局均值（可被剂量整体补偿）与空间变化（场内、版内、径向、疏密）。IRDS 一类路线图把 mask CDU 列进套刻/CD 总预算；先进节点 MEF 常大于 1，版上 1 nm 可以变成晶圆上更大的一截。</p><p><span class="marginnote">术语翻译：mask CDU 就是同一张版上、名义画得一样宽的图形，实际宽度差多少，常报极差（最宽减最窄）或 \\(3\\sigma\\)。它与「平均线宽对不对」是两回事：平均值偏了可以整体调剂量掰回来，散布大了没有单一旋钮。</span></p><p>缺口是<strong>空间指纹</strong>，不是再定义 MEF。把整张版平均 CD 调到规格，不等于 CDU 合格——角上与中心仍可差出窗口。</p><h3 id="疏密项与径向项要分" tabindex="-1">疏密项与径向项要分 <a class="header-anchor" href="#疏密项与径向项要分" aria-label="Permalink to &quot;疏密项与径向项要分&quot;">​</a></h3><p>疏密相关 CD 指向 PEC/MPC；径向或写场拼接指向电子光学、充电与台。混在一个 σ 里，改核或改刻蚀都会打错药。测量必须带位置与局部密度标签。</p><p><span class="marginnote">常见误区：初学者容易以为 CDU 超差就该回去调刻蚀。实际上要看指纹的空间样式：误差跟着图形疏密走的，指向 PEC/MPC 校正不到位；沿半径或写场拼接边走的，指向电子光学与台。不拆样式就改工艺，十有八九打错药。</span></p><p><span class="marginnote">报 mask CDU 时写清：二元铬还是 EUV 吸收体、ADI 还是 AEI、测量的是线还是孔。孔的 CDU 与随机打印是另一账。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>计量：掩模 CD-SEM 或光学掩模计量，按统计抽样覆盖阵列、SRAM、逻辑密度跳变。规格常分 intra-field、intra-mask。反馈：全局偏置改剂量基准；指纹进 PEC/MPC 或写模机校正图。不能靠晶圆 OPC「吃掉」一张每片都不同的掩模指纹——OPC 假定掩模可重复。</p>',13)),(t(),i(n,null,{default:e(()=>[o(s,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20LR%0A%20%20M%5B%22CD%20%E9%87%8F%E6%B5%8B%20%E5%B8%A6%E4%BD%8D%E7%BD%AE%E4%B8%8E%E5%AF%86%E5%BA%A6%E6%A0%87%E7%AD%BE%22%5D%20--%3E%20S1%5B%22%E7%96%8F%E5%AF%86%E7%9B%B8%E5%85%B3%E5%88%86%E9%87%8F%22%5D%0A%20%20M%20--%3E%20S2%5B%22%E5%BE%84%E5%90%91%20%2F%20%E5%86%99%E5%9C%BA%E6%8B%BC%E6%8E%A5%E5%88%86%E9%87%8F%22%5D%0A%20%20M%20--%3E%20S3%5B%22%E5%85%A8%E5%B1%80%E5%9D%87%E5%80%BC%E5%81%8F%E7%BD%AE%22%5D%0A%20%20S1%20--%3E%20R1%5B%22%E8%8D%AF%E6%96%B9%EF%BC%9APEC%20%2F%20MPC%22%5D%0A%20%20S2%20--%3E%20R2%5B%22%E8%8D%AF%E6%96%B9%EF%BC%9A%E7%94%B5%E5%AD%90%E5%85%89%E5%AD%A6%20%2F%20%E5%86%99%E5%9C%BA%E6%A0%A1%E5%87%86%22%5D%0A%20%20S3%20--%3E%20R3%5B%22%E8%8D%AF%E6%96%B9%EF%BC%9A%E5%89%82%E9%87%8F%E5%9F%BA%E5%87%86%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,[E("span",{class:"marginnote"},"这张图回答的问题是：拿到一张 CDU 分布图之后怎么分源、各打什么药。同一个纳米数按「跟疏密走、跟位置走、还是全体一起偏」分成三份，分别由 PEC、写模机校正和剂量基准负责——拆得开才有得治。")],-1)),a[4]||(a[4]=E("p",null,[E("span",{class:"marginnote"},"直觉类比：OPC 像把文件预先「反着扭」好，让打印结果端正——前提是每台打印机歪法都一样。若每张版指纹都不同，预扭就没法做，这就是「OPC 假定掩模可重复」的意思。")],-1)),a[5]||(a[5]=E("p",null,"与写入时间权衡：加密采样、加遍数、降电流，CDU 往往变好，日历变差。量产点是预算交，不是实验室最好 CDU。",-1)),a[6]||(a[6]=E("h2",{id:"机制",tabindex:"-1"},[r("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[7]||(a[7]=E("p",null,"MEF（mask error enhancement factor）把掩模边误差线性（一阶）映到晶圆。低 \\(k_1\\)、助条密集区 MEF 更大，所以 CDU 规格按层类型分，不能全厂一张表。雾化底板造成缓慢 CD 斜坡，像版上 flare；扫描机光学 flare 是另一项，分析要拆。",-1)),(t(),i(n,null,{default:e(()=>[o(s,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20PEC%5B%22PEC%20%2F%20MPC%20%E6%AE%8B%E5%B7%AE%22%5D%20--%3E%20CDU%5B%22mask%20CDU%20%E6%8C%87%E7%BA%B9%22%5D%0A%20%20ETCH%5B%22%E6%8E%A9%E6%A8%A1%E5%88%BB%E8%9A%80%E8%B4%9F%E8%BD%BD%22%5D%20--%3E%20CDU%0A%20%20GRID%5B%22%E5%86%99%E6%A0%85%E9%87%8F%E5%8C%96%22%5D%20--%3E%20CDU%0A%20%20CDU%20--%3E%20MEF%5B%22%C3%97%20MEF%22%5D%0A%20%20MEF%20--%3E%20WCD%5B%22%E6%99%B6%E5%9C%86%20CD%20%E9%A2%84%E7%AE%97%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=l('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>CDU 不含空白片缺陷、不含 pellicle 热指纹（后者在上机后出现）。不编造某节点「mask CDU = 0.x nm」的宇宙常数——规格随层与代工厂包变，只引用路线图<strong>结构</strong>（有这项预算），不抄未公开的厂内数。</p><p>后课默认：尺寸均匀性已从写入/刻蚀收账；下一课处理位置——图形中心放错，套刻预算先被版吃掉一截。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Mask CDU 是空间变化，不是平均 CD；进晶圆时乘 MEF。</li><li>疏密项与径向/拼接项分源，才能决定改 PEC 还是改台。</li><li>OPC 吃不掉每张版不同的指纹。</li><li>出处：ITRS/IRDS 掩模误差预算结构；MEF 与 mask CDU 的产线通称。</li></ul>',5))])}const k=C(A,[["render",p]]);export{f as __pageData,k as default};
